choose.when:
SELECT o.opp_id AS "targetId",o.ctrt_type_cd AS "contractType",o.cust_clnt_id AS "customerId",c.induty_cd AS industry,
  o.work_plc_addr AS address,o.rmrk AS feature,NULL::date AS "startDate",NULL::date AS "endDate",o.opp_stat_cd AS status
FROM tb_sl_opp o LEFT JOIN tb_bs_clnt c ON c.clnt_id=o.cust_clnt_id WHERE o.opp_id=#{targetId}

choose.otherwise:
SELECT p.proj_id AS "targetId",p.ctrt_type_cd AS "contractType",p.cust_clnt_id AS "customerId",c.induty_cd AS industry,
  p.work_plc_addr AS address,p.feature_cn AS feature,p.ctrt_bgn_dt AS "startDate",p.ctrt_end_dt AS "endDate",p.proj_stat_cd AS status
FROM tb_pj_proj p LEFT JOIN tb_bs_clnt c ON c.clnt_id=p.cust_clnt_id WHERE p.proj_id=#{targetId}

mapper.select:
SELECT DISTINCT r.dev_id AS "developerId" FROM tb_sl_rcmd_log r
WHERE r.rcmd_type_cd='AI' AND r.user_act_cd='EXCL' AND r.job_cd=#{jobCode}
AND r.opp_id=#{targetId}AND r.proj_id=#{targetId}
  AND NOT EXISTS(SELECT 1 FROM tb_sy_chg_hist h WHERE h.trgt_tbl_nm='TB_SL_OPP''TB_PJ_PROJ'
    AND h.trgt_key=#{targetId} AND (h.chg_type_cd='RESUME' OR (h.chg_item_nm IN ('OPP_STAT_CD','PROJ_STAT_CD') AND h.bfr_val='STOP' AND h.aft_val='ING')) AND h.reg_dttm>r.act_dttm)

SELECT o.opp_nm AS "opportunityName",o.sales_step_cd AS "salesStepCode",o.cust_clnt_id AS "customerId",c.clnt_nm AS "customerName",
  EXISTS(SELECT 1 FROM tb_sl_tent_asgn t WHERE t.opp_id=o.opp_id AND t.need_sn=CAST(#{needSn} AS numeric) AND t.dev_id=#{developerId} AND t.tent_stat_cd='ACT') AS "alreadyTentativelyAssigned"
FROM tb_sl_opp o LEFT JOIN tb_bs_clnt c ON c.clnt_id=o.cust_clnt_id WHERE o.opp_id=#{opportunityId}
